arguments.newString:
# Python UTF-8 mode — primary home: ~/.config/powershell/profile.ps1 (local profile).
# These entries are fallback/belt-and-suspenders for sessions where the local profile
# is unavailable. Idempotent — no harm if already set by the local profile.
# PYTHONUTF8=1 (PEP 540) + PYTHONIOENCODING=utf-8 (PEP 597) are both required:
# PYTHONUTF8 activates UTF-8 mode globally; PYTHONIOENCODING covers stream encoding
# when invoked from pipes or without a controlling tty.
if (-not $env:PYTHONUTF8) { $env:PYTHONUTF8 = "1" }
if (-not $env:PYTHONIOENCODING) { $env:PYTHONIOENCODING = "utf-8" }

# pwsh pipeline serialization encoding — covers pwsh | python and pwsh | bun pipes.
if (-not $OutputEncoding -or $OutputEncoding.CodePage -ne 65001) {
    $OutputEncoding = [System.Text.Encoding]::UTF8
}

